const canvas = document.getElementById('fanChart');
        const ctx = canvas.getContext('2d');
        let centerX, centerY, radius;
        let selectedAngle = null;
        let lineThickness = 3;
        let isNightMode = false;
        let currentEye = 'left';
        let blurIntensity = 4;
        let pendingAngle = null; // Stored angle before confirmation
        // Resize Canvas nicely
        function resizeCanvas() {
            const container = document.getElementById('chart-container');
            const size = Math.min(container.clientWidth, 600);
            canvas.style.width = size + "px";
            canvas.style.height = size + "px";
            canvas.width = size;
            canvas.height = size;
            centerX = canvas.width / 2;
            centerY = canvas.height / 2;
            radius = (size / 2) - 40;
            drawChart();
        }
        function drawChart() {
            ctx.fillStyle = isNightMode ? '#000000' : '#ffffff';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            const lineColor = isNightMode ? '#ffffff' : '#0f172a';
            const highlightColor = '#0ea5e9';
            const labelColor = isNightMode ? '#64748b' : '#94a3b8';
            for (let i = 0; i < 180; i += 10) {
                const isSelected = (selectedAngle !== null && i === selectedAngle);
                drawRadius(i, isSelected, lineColor, highlightColor, labelColor);
            }
            // Center Dot
            ctx.beginPath();
            ctx.arc(centerX, centerY, 6, 0, 2 * Math.PI);
            ctx.fillStyle = isNightMode ? '#333' : '#cbd5e1';
            ctx.fill();
        }
        function drawRadius(angle, isSelected, regularColor, activeColor, textColor) {
            const rad = (angle * Math.PI) / 180;
            const x1 = centerX + radius * Math.cos(rad);
            const y1 = centerY + radius * Math.sin(rad);
            const x2 = centerX - radius * Math.cos(rad);
            const y2 = centerY - radius * Math.sin(rad);
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            if (isSelected) {
                ctx.lineWidth = lineThickness + 4;
                ctx.strokeStyle = activeColor;
                ctx.shadowBlur = 15;
                ctx.shadowColor = activeColor;
            } else {
                ctx.lineWidth = lineThickness;
                ctx.strokeStyle = regularColor;
                ctx.shadowBlur = 0;
            }
            ctx.lineCap = 'round';
            ctx.stroke();
            ctx.shadowBlur = 0;
            if (!isSelected || selectedAngle === null) {
                const textPad = 25;
                const lx = centerX + (radius + textPad) * Math.cos(rad);
                const ly = centerY + (radius + textPad) * Math.sin(rad);
                ctx.font = "bold 12px Inter";
                ctx.fillStyle = textColor;
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";
                let labelAngle = -angle;
                if (labelAngle < 0) labelAngle += 360;
                if (labelAngle > 180) labelAngle -= 180;
                if (labelAngle === 0) labelAngle = 180;
                ctx.fillText(labelAngle + "°", lx, ly);
            }
        }
        // Interaction
        canvas.addEventListener('click', function (event) {
            const rect = canvas.getBoundingClientRect();
            const scaleX = canvas.width / rect.width;
            const scaleY = canvas.height / rect.height;
            const mouseX = (event.clientX - rect.left) * scaleX;
            const mouseY = (event.clientY - rect.top) * scaleY;
            const dy = mouseY - centerY;
            const dx = mouseX - centerX;
            let theta = Math.atan2(dy, dx);
            let degrees = theta * (180 / Math.PI);
            if (degrees < 0) degrees += 360;
            let snapped = Math.round(degrees / 10) * 10;
            if (snapped >= 180) snapped -= 180;
            // NEW: Step 1 of Gamification - Select but don't show results yet
            selectedAngle = snapped;
            pendingAngle = snapped;
            drawChart();
            showConfidenceStep();
        });
        // Gamification: Show Confidence Slider
        function showConfidenceStep() {
            document.getElementById('confidence-step').classList.remove('hidden');
            document.getElementById('results-panel').classList.add('hidden');
            // Smooth scroll
            document.getElementById('confidence-step').scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
        // Gamification: Reveal Results with Animation
        function revealResults() {
            const btn = document.querySelector('#confidence-step button');
            const originalText = btn.innerText;
            // Dopamine Animation: "Analyzing..."
            btn.innerText = "Processing Optical Data...";
            btn.disabled = true;
            btn.classList.add('bg-slate-800');
            setTimeout(() => {
                btn.innerText = originalText;
                btn.disabled = false;
                btn.classList.remove('bg-slate-800');
                document.getElementById('confidence-step').classList.add('hidden');
                finalizeResults(pendingAngle);
            }, 800); // 800ms delay for suspense
        }
        function finalizeResults(angle) {
            let displayAngle = -angle;
            if (displayAngle < 0) displayAngle += 360;
            if (displayAngle >= 180) displayAngle -= 180;
            if (displayAngle === 0) displayAngle = 180;
            let corrective = displayAngle + 90;
            if (corrective > 180) corrective -= 180;
            document.getElementById('results-panel').classList.remove('hidden');
            document.getElementById('result-angle').innerText = corrective + "°";
            document.getElementById('res-meridian').innerText = displayAngle;
            document.getElementById('res-axis').innerText = corrective;
            updateSimulation(displayAngle);
            window.scrollTo({ top: document.getElementById('results-panel').offsetTop - 100, behavior: 'smooth' });
        }
        function updateSimulation(sharpMeridian) {
            let blurAngle = sharpMeridian + 90;
            let rad = blurAngle * (Math.PI / 180);
            let xBlur = Math.abs(Math.cos(rad) * blurIntensity);
            let yBlur = Math.abs(Math.sin(rad) * blurIntensity);
            const filter = document.getElementById('blur-filter-val');
            filter.setAttribute('stdDeviation', `${xBlur} ${yBlur}`);
        }
        function updateBlurIntensity(val) {
            blurIntensity = val;
            if (selectedAngle !== null) {
                let displayAngle = -selectedAngle;
                if (displayAngle < 0) displayAngle += 360;
                if (displayAngle >= 180) displayAngle -= 180;
                if (displayAngle === 0) displayAngle = 180;
                updateSimulation(displayAngle);
            }
        }
        function toggleNightMode() {
            isNightMode = !isNightMode;
            const wrapper = document.getElementById('chart-container');
            const btn = document.getElementById('btn-night');
            if (isNightMode) {
                wrapper.classList.add('night-mode');
                btn.classList.add('bg-slate-800', 'text-white');
                btn.classList.remove('bg-white', 'text-slate-600');
            } else {
                wrapper.classList.remove('night-mode');
                btn.classList.remove('bg-slate-800', 'text-white');
                btn.classList.add('bg-white', 'text-slate-600');
            }
            drawChart();
        }
        function updateThickness(val) {
            lineThickness = parseInt(val);
            drawChart();
        }
        function resetChart() {
            selectedAngle = null;
            document.getElementById('results-panel').classList.add('hidden');
            document.getElementById('confidence-step').classList.add('hidden');
            drawChart();
        }
        function hideOverlay() {
            document.getElementById('start-overlay').classList.add('hidden');
            // Trigger a hint 5 seconds after starting
            setTimeout(() => {
                showHint("Tip: Sit about 20 inches (50cm) from the screen.");
            }, 5000);
        }
        function setEye(eye) {
            currentEye = eye;
            resetChart();
            const btnL = document.getElementById('btn-left');
            const btnR = document.getElementById('btn-right');
            const activeClass = "bg-sky-600 text-white shadow-lg";
            const inactiveClass = "bg-white text-slate-400 hover:text-slate-600";
            if (eye === 'left') {
                btnL.className = `px-5 py-2 text-[10px] font-black rounded-lg transition-all uppercase tracking-widest flex items-center gap-2 ${activeClass}`;
                btnR.className = `px-5 py-2 text-[10px] font-black rounded-lg transition-all uppercase tracking-widest flex items-center gap-2 ${inactiveClass}`;
            } else {
                btnR.className = `px-5 py-2 text-[10px] font-black rounded-lg transition-all uppercase tracking-widest flex items-center gap-2 ${activeClass}`;
                btnL.className = `px-5 py-2 text-[10px] font-black rounded-lg transition-all uppercase tracking-widest flex items-center gap-2 ${inactiveClass}`;
            }
            document.getElementById('start-overlay').classList.remove('hidden');
        }
        /* --- TUTORIAL / ONBOARDING LOGIC --- */
        let tutorialStep = 0;
        const steps = [
            { id: 'eye-toggle-container', text: "Start by selecting which eye to test." },
            { id: 'mode-toggle-container', text: "Toggle Night Mode to check for starbursts." },
            { id: 'slider-container', text: "Adjust line thickness if they look too faint." },
            { id: 'chart-container', text: "Click the Darkest Line on the fan." }
        ];
        function startTutorial() {
            const dimmer = document.getElementById('tutorial-dimmer');
            dimmer.classList.remove('hidden');
            setTimeout(() => dimmer.classList.remove('opacity-0'), 10);
            tutorialStep = 0;
            highlightStep();
        }
        function highlightStep() {
            if (tutorialStep >= steps.length) {
                endTutorial();
                return;
            }
            // Clean up previous
            document.querySelectorAll('.tutorial-active').forEach(el => el.classList.remove('tutorial-active'));
            // Remove any tooltips attached to body
            document.querySelectorAll('.tutorial-tooltip-global').forEach(el => el.remove());
            const step = steps[tutorialStep];
            const el = document.getElementById(step.id);
            if (el) {
                el.classList.add('tutorial-active');
                // Create Tooltip - ATTACH TO BODY to avoid overflow:hidden clipping and Z-index wars
                const tooltip = document.createElement('div');
                tooltip.className = 'tutorial-tooltip-global fixed bg-white text-slate-800 p-4 rounded-xl shadow-2xl z-[100] w-64 text-sm font-bold border border-sky-200 transition-all duration-300';
                tooltip.innerHTML = `
                    <p class="mb-3">${step.text}</p>
                    <button onclick="nextStep()" class="bg-sky-500 text-white px-3 py-1 rounded text-xs uppercase tracking-wider hover:bg-sky-600 shadow-md">Next</button>
                `;
                document.body.appendChild(tooltip);
                // Position logic using getBoundingClientRect
                const rect = el.getBoundingClientRect();
                // Default position: Below the element
                let top = rect.bottom + 15;
                let left = rect.left + (rect.width / 2) - 128; // Center (128 is half of w-64)
                // Edge detection
                if (left < 10) left = 10;
                if (left + 256 > window.innerWidth) left = window.innerWidth - 266;
                if (top + 100 > window.innerHeight) {
                    // Flip to top if no space below
                    top = rect.top - 120;
                }
                tooltip.style.top = `${top}px`;
                tooltip.style.left = `${left}px`;
                // Animation entry
                requestAnimationFrame(() => {
                    tooltip.style.opacity = '1';
                    tooltip.style.transform = 'translateY(0)';
                });
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
        function nextStep() {
            tutorialStep++;
            highlightStep();
        }
        function endTutorial() {
            const dimmer = document.getElementById('tutorial-dimmer');
            dimmer.classList.add('opacity-0');
            setTimeout(() => dimmer.classList.add('hidden'), 300);
            document.querySelectorAll('.tutorial-active').forEach(el => el.classList.remove('tutorial-active'));
            document.querySelectorAll('.tutorial-tooltip-global').forEach(el => el.remove());
        }
        /* --- SMART HINTS SYSTEM --- */
        function showHint(msg) {
            const container = document.getElementById('hint-container');
            const hint = document.createElement('div');
            hint.className = 'hint-toast bg-white border-l-4 border-sky-500 shadow-xl p-4 rounded-r-lg flex items-center gap-3 max-w-sm';
            hint.innerHTML = `
                <span class="text-xl">💡</span>
                <p class="text-xs font-semibold text-slate-600">${msg}</p>
                <button onclick="this.parentElement.remove()" class="ml-auto text-slate-300 hover:text-slate-500">×</button>
            `;
            container.appendChild(hint);
            setTimeout(() => {
                hint.style.opacity = '0';
                setTimeout(() => hint.remove(), 500);
            }, 6000);
        }
        // Init
        window.addEventListener('resize', () => {
            resizeCanvas();
            // Re-calc tooltip position if active
            if (document.querySelector('.tutorial-active')) {
                highlightStep(); // Re-trigger to update position
            }
        });
        window.addEventListener('load', () => {
            resizeCanvas();
            // Show start hint after 2 seconds
            setTimeout(() => showHint("Welcome! Click 'Guide Me' for a quick tour."), 2000);
        });
